/**
 * Interface for path normalization adapters
 * Provides only environment-specific tools that must be implemented differently per platform
 * Implementations can be swapped based on environment (Node.js, browser, etc.)
 */

/**
 * System information needed for path normalization
 */
interface SystemInfo {
    homeDir: string;
    pathSeparator: string;
    platform: 'win32' | 'darwin' | 'linux' | string;
}
/**
 * Interface for path normalization adapters
 * Provides environment-specific tools for path processing
 */
interface PathNormalizationAdapter {
    /**
     * Get raw repository information for a given path (no caching)
     * @param absolutePath Absolute file system path
     * @returns Repository information if path is in a git repository, null otherwise
     *
     * Implementation notes:
     * - Should populate the `branch` field by running `git rev-parse --abbrev-ref HEAD`
     * - Should populate the `headCommit` field by running `git rev-parse HEAD`
     * - Branch information represents the current branch at analysis time
     * - May return null for detached HEAD states
     * - Head commit is the SHA of the current HEAD commit
     */
    getRawRepositoryInfo(absolutePath: string): Promise<RepositoryInfo | null>;
    /**
     * Get system information (home directory, path separator, etc.)
     * @returns System-specific information needed for path processing
     */
    getSystemInfo(): SystemInfo;
    /**
     * Resolve a relative path to absolute path
     * @param relativePath Relative path to resolve
     * @param workingDirectory Working directory to resolve against
     * @returns Absolute path
     */
    resolvePath(relativePath: string, workingDirectory: string): string;
    /**
     * Check if a path is absolute
     * @param path Path to check
     * @returns true if path is absolute
     */
    isAbsolutePath(path: string): boolean;
    /**
     * Get relative path from one path to another
     * @param fromPath Source path
     * @param toPath Target path
     * @returns Relative path from source to target
     */
    getRelativePath(fromPath: string, toPath: string): string;
    /**
     * Check if the adapter is available in the current environment
     * @returns true if path normalization is supported
     */
    isAvailable(): boolean;
}
/**
 * Mock adapter for testing
 */
declare class MockPathNormalizationAdapter implements PathNormalizationAdapter {
    private mockSystemInfo;
    private mockRepositories;
    constructor(mockSystemInfo?: SystemInfo, mockRepositories?: Map<string, RepositoryInfo>);
    getRawRepositoryInfo(absolutePath: string): Promise<RepositoryInfo | null>;
    getSystemInfo(): SystemInfo;
    resolvePath(relativePath: string, workingDirectory: string): string;
    isAbsolutePath(path: string): boolean;
    getRelativePath(fromPath: string, toPath: string): string;
    isAvailable(): boolean;
    addMockRepository(root: string, info: RepositoryInfo): void;
    setMockSystemInfo(info: SystemInfo): void;
}

/**
 * Path normalization types for agent session events
 * Handles classification and normalization of file paths from tool events
 */

/**
 * Supported platforms for path normalization
 */
type SupportedPlatform = 'darwin' | 'linux';
/**
 * Check if platform is supported for path operations
 */
declare function isPlatformSupported(platform: string): platform is SupportedPlatform;
/**
 * Validate platform support and throw if unsupported
 */
declare function validatePlatformSupport(systemInfo: SystemInfo): void;
/**
 * Repository information for path normalization
 */
interface RepositoryInfo {
    root: string;
    remoteUrl?: string;
    owner?: string;
    repo?: string;
    branch?: string;
    headCommit?: string;
}
/**
 * Classification of file paths based on their context
 */
declare enum PathContext {
    REPO_FILE = "repo_file",// File within a git repository
    SYSTEM_FILE = "system_file",// System/library files (e.g., node_modules)
    USER_FILE = "user_file",// User files outside any repo
    TEMP_FILE = "temp_file",// Temporary files
    CONFIG_FILE = "config_file"
}
/**
 * Normalized path information with repository context
 */
interface NormalizedPathInfo {
    originalPath: string;
    absolutePath: string;
    context: PathContext;
    repository?: {
        gitRoot: string;
        relativePath: string;
        remoteUrl?: string;
        owner?: string;
        repo?: string;
    };
    displayPath: string;
}
/**
 * File operation types for tracking
 */
declare enum FileOperation {
    READ = "read",
    WRITE = "write",
    CREATE = "create",
    DELETE = "delete",
    EDIT = "edit",
    SEARCH = "search",
    LIST = "list"
}
/**
 * Helper to determine file operation from tool name
 */
declare function getFileOperation(toolName: string): FileOperation | undefined;
/**
 * Extract file paths from tool input based on tool name
 * @deprecated Use extractFilePathsFromTool instead which handles both input and output
 */
declare function extractFilePathsFromToolInput(toolName: string, toolInput: any): string[];
/**
 * Extract file paths from tool output/response based on tool name
 * Based on audit findings from 23,037 real Claude events
 */
declare function extractFilePathsFromToolOutput(toolName: string, toolOutput: any): string[];
/**
 * Comprehensive path extraction from both tool input and output
 * Combines extraction from all discovered fields based on audit
 * @param toolName The name of the tool
 * @param toolInput The tool's input parameters
 * @param toolOutput The tool's output/response (optional)
 * @param systemInfo System information for platform validation (optional, defaults to Unix)
 * @throws Error if platform is not supported
 */
declare function extractFilePathsFromTool(toolName: string, toolInput: any, toolOutput?: any, systemInfo?: SystemInfo): string[];
/**
 * Check if a path is absolute (Unix-style only)
 * @param filePath The file path to check
 * @param systemInfo Optional system info for validation
 * @throws Error if platform is not supported
 */
declare function isAbsolutePath(filePath: string, systemInfo?: SystemInfo): boolean;
/**
 * Classify a file path based on patterns
 */
declare function classifyPath(absolutePath: string): PathContext;

/**
 * Normalized event structure for all agent session events
 * This provides a consistent interface across different agents (Claude, Gemini, OpenCode, etc.)
 */

/**
 * Known event types across all agents
 * Using 'unknown' for events we haven't categorized yet
 */
type NormalizedEventType = 'pre-tool-use' | 'post-tool-use' | 'notification' | 'user-prompt-submit' | 'stop' | 'subagent-stop' | 'pre-compact' | 'session-start' | 'lifecycle' | 'unknown';
/**
 * Common tool names across agents
 * This is a union of known tools, but we accept string for flexibility
 */
type CommonToolName = 'Task' | 'Bash' | 'Glob' | 'Grep' | 'Read' | 'Edit' | 'MultiEdit' | 'Write' | 'WebFetch' | 'WebSearch' | 'LS' | 'TodoWrite' | 'NotebookRead' | 'NotebookEdit' | 'ExitPlanMode' | string;
/**
 * Normalized agent session event
 * This is what all agent event processors should return
 */
interface NormalizedAgentSessionEvent {
    eventType: NormalizedEventType;
    sessionId: string;
    workingDirectory: string;
    normalizedWorkingDirectory?: string;
    transcriptPath?: string;
    timestamp: number;
    toolName?: CommonToolName;
    toolInput?: unknown;
    toolOutput?: unknown;
    files?: NormalizedPathInfo[];
    operation?: FileOperation;
    data?: {
        prompt?: string;
        message?: string;
        stopHookActive?: boolean;
        trigger?: 'manual' | 'auto';
        customInstructions?: string;
        source?: 'startup' | 'resume' | 'clear';
        [key: string]: unknown;
    };
    raw: unknown;
    provider: SupportedAgent;
}
/**
 * Helper to determine if an event is a tool event
 */
declare function isToolEvent(event: NormalizedAgentSessionEvent): boolean;
/**
 * Helper to determine if an event is a stop event
 */
declare function isStopEvent(event: NormalizedAgentSessionEvent): boolean;

/**
 * Universal event structure after agent-specific normalization
 * Contains raw path strings that need repository-specific processing
 *
 * This is an intermediate format that bridges agent-specific processors
 * and path normalization services. Agent processors extract raw paths
 * as strings, and the path normalization service enriches them with
 * repository and system context.
 */

/**
 * Universal event structure after agent-specific normalization
 * Contains raw path strings that need repository-specific processing
 */
interface UniversalAgentSessionEvent {
    eventType: NormalizedEventType;
    sessionId: string;
    workingDirectory: string;
    transcriptPath?: string;
    timestamp: number;
    toolName?: CommonToolName;
    toolInput?: unknown;
    toolOutput?: unknown;
    rawFilePaths?: string[];
    operation?: FileOperation;
    data?: {
        prompt?: string;
        message?: string;
        stopHookActive?: boolean;
        trigger?: 'manual' | 'auto';
        customInstructions?: string;
        source?: 'startup' | 'resume' | 'clear';
        [key: string]: unknown;
    };
    raw: unknown;
    provider: SupportedAgent;
}
/**
 * Type guard to check if an object is a universal agent session event
 */
declare function isUniversalAgentSessionEvent(obj: unknown): obj is UniversalAgentSessionEvent;

/**
 * Repository-normalized universal agent session event
 * This is the final normalized event structure after path normalization
 * It extends UniversalAgentSessionEvent with fully processed path information
 */

/**
 * Repository context for the event
 * This is typically the repository of the working directory
 */
interface EventRepositoryContext extends RepositoryInfo {
    root: string;
}
/**
 * Final event structure after repository path normalization
 * Replaces raw file paths with normalized path information
 */
interface RepoNormalizedUniversalAgentSessionEvent extends Omit<UniversalAgentSessionEvent, 'rawFilePaths'> {
    repository?: EventRepositoryContext;
    files?: NormalizedPathInfo[];
    normalizedWorkingDirectory?: string;
}

/**
 * Centralized service for normalizing paths in universal agent session events
 * Uses a PathNormalizationAdapter to access environment-specific tools
 *
 * Focuses on repository detection and relative path calculation:
 * - Files in current repository: relative path from git root
 * - Files in other repositories: identify repo and provide relative path
 * - Files outside repositories: keep absolute path
 */

/**
 * Centralized service for path normalization
 */
declare class PathNormalizationService {
    private adapter;
    constructor(adapter: PathNormalizationAdapter);
    /**
     * Normalize a universal agent session event by processing its raw file paths
     * @param event Universal agent session event with raw path strings
     * @returns Repository-normalized event with structured path information
     * @throws Error if platform is not supported
     */
    normalizePaths(event: UniversalAgentSessionEvent): Promise<RepoNormalizedUniversalAgentSessionEvent>;
    /**
     * Normalize a single file path with cached repository info
     * @param filePath Raw file path from the event
     * @param workingDirectory Working directory context
     * @param cachedRepoInfo Cached repository info for working directory (optimization)
     * @returns Normalized path information
     */
    normalizePathWithCache(filePath: string, workingDirectory: string, cachedRepoInfo: RepositoryInfo | null): Promise<NormalizedPathInfo>;
    /**
     * Normalize a single file path (legacy method for backward compatibility)
     * @param filePath Raw file path from the event
     * @param workingDirectory Working directory context
     * @returns Normalized path information
     */
    normalizePath(filePath: string, workingDirectory: string): Promise<NormalizedPathInfo>;
    /**
     * Normalize working directory to repository root
     * @param workingDirectory Raw working directory path
     * @returns Repository root if in a git repo, otherwise original path
     */
    normalizeWorkingDirectory(workingDirectory: string): Promise<string>;
}

